+                            return b -> b.value(ESTestCase.randomLongBetween(1000, 2000));
+                        }
+                    })
+                )
+            )
+            .build());
+    }
+
+    DataGenerator getDataGenerator() {
+        return dataGenerator;
+    }
+
+    void logsDbMapping(XContentBuilder builder) throws IOException {
